import { readFileSync } from "fs";
import { join } from "path";

const {
  applyReleaseSigning,
  setReleaseGradleProperties,
} = require("../../../plugins/withReleaseSigning");

/** app/build.gradle as generated by Expo SDK 56 prebuild. */
const generated = readFileSync(join(__dirname, "../fixtures/build.gradle.txt"), "utf8");

const KEYS = [
  "ANDROID_UPLOAD_STORE_FILE",
  "ANDROID_UPLOAD_STORE_PASSWORD",
  "ANDROID_UPLOAD_KEY_ALIAS",
  "ANDROID_UPLOAD_KEY_PASSWORD",
];

/** Text of the `name { ... }` block that starts at `from`, braces balanced. */
function block(source: string, name: string, from = 0): string {
  const start = source.indexOf(`${name} {`, from);
  if (start < 0) throw new Error(`no ${name} block`);
  let depth = 0;
  for (let i = source.indexOf("{", start); i < source.length; i++) {
    if (source[i] === "{") depth++;
    if (source[i] === "}" && --depth === 0) return source.slice(start, i + 1);
  }
  throw new Error(`unbalanced ${name} block`);
}

describe("applyReleaseSigning", () => {
  const result: string = applyReleaseSigning(generated);
  const buildTypes = block(result, "buildTypes");
  const signingConfigs = block(result, "signingConfigs");

  it("reads the four upload key variables from the environment, then from mobile/.env", () => {
    for (const key of KEYS) expect(result).toContain(`"${key}"`);
    expect(result).toContain("System.getenv(key)");
    expect(result).toContain('new File(projectRoot, ".env")');
  });

  it("signs release builds with the release config, never with the debug key", () => {
    const release = block(buildTypes, "release");
    expect(release).not.toContain("signingConfigs.debug");
    expect(release).toContain("signingConfigs.release");
    expect(block(buildTypes, "debug")).toContain("signingConfig signingConfigs.debug");
  });

  it("adds a release signing config next to the debug one", () => {
    const release = block(signingConfigs, "release");
    expect(release).toContain("storeFile file(releaseSigning.values.ANDROID_UPLOAD_STORE_FILE)");
    expect(release).toContain("keyAlias releaseSigning.values.ANDROID_UPLOAD_KEY_ALIAS");
    expect(block(signingConfigs, "debug")).toContain("debug.keystore");
  });

  it("fails only release packaging when the key is missing", () => {
    expect(result).toContain("gradle.taskGraph.whenReady");
    expect(result).toContain('"packageRelease"');
    expect(result).toContain('"bundleRelease"');
    expect(result).toContain("Release signing is not configured. Missing:");
  });

  it("names missing variables but never prints their values", () => {
    const logging = (text: string) => text.match(/println|logger\./g)?.length ?? 0;
    expect(logging(result)).toBe(logging(generated));
    expect(result).not.toMatch(/\$\{?releaseSigning\.values/);
  });

  it("is idempotent", () => {
    expect(applyReleaseSigning(result)).toBe(result);
  });

  it("fails loudly when the Expo template no longer has the expected anchors", () => {
    expect(() => applyReleaseSigning("android {}")).toThrow(/withReleaseSigning/);
  });
});

describe("setReleaseGradleProperties", () => {
  type Item = { type: "property"; key: string; value: string } | { type: "comment"; value: string };

  function value(items: Item[], key: string) {
    return items.filter((item) => item.type === "property" && item.key === key);
  }

  it("turns on R8 and resource shrinking, replacing old values without duplicates", () => {
    const items: Item[] = setReleaseGradleProperties([
      { type: "comment", value: "generated" },
      { type: "property", key: "hermesEnabled", value: "true" },
      { type: "property", key: "android.enableMinifyInReleaseBuilds", value: "false" },
    ]);
    for (const key of [
      "android.enableMinifyInReleaseBuilds",
      "android.enableShrinkResourcesInReleaseBuilds",
    ]) {
      expect(value(items, key)).toEqual([{ type: "property", key, value: "true" }]);
    }
    expect(value(items, "hermesEnabled")).toHaveLength(1);
    expect(items[0]).toEqual({ type: "comment", value: "generated" });
  });
});
